cases.script:
strip() { /usr/bin/sed -E 's/^[^:]*: line [0-9]+: //' "$1" | /usr/bin/tr '\n' '|'; }
show() { printf '%s status=%s out=' "$1" "$2"; /usr/bin/tr '\n' '|' < /tmp/rf.out; printf ' err='; strip /tmp/rf.err; echo; }
r() { local l=$1; shift; "$@" >/tmp/rf.out 2>/tmp/rf.err; show "$l" $?; }
u() { local g=--clear-groups; [[ $3 ]] && g=--groups=$3
  /usr/bin/setpriv --reuid=2000 --regid=2000 $g -- "$BASH" --noprofile --norc -c "$2" >/tmp/rf.out 2>/tmp/rf.err; show "$1" $?; }
RT=/tmp/rt; /usr/bin/mkdir -p $RT
seed() { /usr/bin/python3 -c 'import sys; n=int(sys.argv[2]); open(sys.argv[1],"wb").write(bytes((i*7+i//251)%256 for i in range(n)))' "$1" "$2"; }
sz() { /usr/sbin/blockdev --getsize64 "$1"; }
sha() { /usr/bin/sha256sum < "$1" | /usr/bin/cut -c1-16; }
# udev probes each new loop device; settle before detaching so the detach is
# immediate, and wait for sysfs to drop the association before the next attach.
settle() { /usr/bin/udevadm settle -t 10 >/dev/null 2>&1; }
gone() { local x=${1#/dev/} i; for ((i=0;i<50;i++)); do [[ -e /sys/block/$x/loop/backing_file ]] || return 0; /usr/bin/sleep 0.1; done; echo "  $x still attached"; }
att() { /usr/sbin/losetup "$@"; settle; }
detach() { local d; for d; do /usr/sbin/losetup -d $d; gone $d; done; }
I=$RT/sw.img M=$RT/mnt
/usr/bin/truncate -s 6M $I && /usr/sbin/mkfs.ext4 -q -F -O ^has_journal $I && /usr/bin/mkdir -p $M && /usr/bin/mount -o loop $I $M || { echo SETUP-FAILED; exit 99; }
n=0; mkfile() { n=$((n+1)); /usr/bin/dd if=/dev/zero of="$M/$1" bs=64k count=16 status=none && /usr/bin/chmod 0600 "$M/$1" &&
  { [[ $2 == raw ]] || /usr/sbin/mkswap -q -U 00000000-0000-4000-8000-00000000000$n -L "sw$n" "$M/$1" >/dev/null; } || echo SETUP-FAILED; }
swaps() { /usr/bin/tail -n +2 /proc/swaps | /usr/bin/awk '{print "  swap", $1, $2, $3, $5}'; echo "  swaps=$(( $(/usr/bin/wc -l < /proc/swaps) - 1 ))"; }
endswap() { /usr/bin/tail -n +2 /proc/swaps | while read -r p _; do /usr/sbin/swapoff "$p"; done; cd /tmp/parity-case; /usr/bin/umount $M && echo teardown=ok; }
mkfile s1; mkfile s2
swaps
for a in "" -s --show --summary; do r "empty[$a]" swapon $a; done
/usr/sbin/swapon -p 5 $M/s1 && /usr/sbin/swapon -p 3 $M/s2 || echo SETUP-FAILED
swaps
for a in "" -s --show --summary; do r "two[$a]" swapon $a; done
: > $RT/noread; /usr/bin/chmod 000 $RT/noread; /usr/bin/mount --bind $RT/noread /proc/swaps || echo SETUP-FAILED
/usr/bin/setpriv --bounding-set=-dac_override,-dac_read_search -- "$BASH" --noprofile --norc -c 'swapon --show' >/tmp/rf.out 2>/tmp/rf.err; show unreadable $?
/usr/bin/umount /proc/swaps
endswap

